/** Original, editable modeled Casino icons. Shared GPU/CPU geometry + alpha shadows. */
import * as THREE from './vendor/three.module.js';
import { smoothGeometryNormals } from './art-text-mesh.js';
import { renderSoftwareScene } from './art-software-renderer.js';
import { compositeArtwork } from './art-composite.js';
const engines=new WeakMap(),environments=new WeakMap();
const radians=n=>n*Math.PI/180;
const mix=(a,b,t)=>'#'+new THREE.Color(a).lerp(new THREE.Color(b),t).getHexString();
const point=(x,y,z)=>new THREE.Vector3(x,y,z);
function physical(color,options={}){return new THREE.MeshPhysicalMaterial({color,roughness:.21,metalness:.58,clearcoat:.9,clearcoatRoughness:.11,envMapIntensity:1.1,...options});}
function rampMaterial(color,doc,gloss,kind='metal'){
  const silver=new THREE.Color(color).getHSL({}).s<.25;
  const stops=kind==='metal'?[[0,mix(color,'#fff3b0',.42)],[.08,color],[.30,mix(color,'#6b3004',.18)],[.45,mix(color,'#301109',.70)],[.52,mix(color,'#23121b',.79)],[.62,color],[.76,mix(color,'#fff5bb',.24)],[.83,mix(color,'#fff5bb',.49)],[.89,color],[1,mix(color,'#4b1a0a',silver?.27:.42)]]:
    [[0,mix(color,'#ffffff',.20)],[.14,color],[.35,color],[.50,mix(color,'#08071a',.72)],[.62,color],[.82,mix(color,'#ffffff',.15)],[.90,color],[1,mix(color,'#080517',.45)]];
  const c=doc.createElement('canvas');c.width=4;c.height=512;const ctx=c.getContext('2d'),g=ctx.createLinearGradient(0,0,0,512);for(const[a,col]of stops)g.addColorStop(a,col);ctx.fillStyle=g;ctx.fillRect(0,0,4,512);
  const texture=new THREE.CanvasTexture(c);texture.colorSpace=THREE.SRGBColorSpace;
  const mat=physical('#ffffff',{map:texture,metalness:kind==='metal'?.78:.22,roughness:.52-gloss/100*.37,clearcoat:gloss/100});
  mat.userData={studioBands:stops,studioSurface:kind,studioBaseColor:color};return mat;
}
function materials(p,doc,o){return {gold:rampMaterial(p.metal,doc,o.gloss),goldSide:physical(mix(p.metal,'#4a1c09',.34),{metalness:.85,roughness:.19}),pale:physical(mix(p.metal,'#fff0c0',.24),{metalness:.76,roughness:.13}),body:rampMaterial(p.body,doc,o.gloss,'lacquer'),primary:rampMaterial(p.primary,doc,o.gloss,'lacquer'),dark:physical(p.dark,{metalness:.34,roughness:.28}),gem:physical(p.gem,{metalness:.38,roughness:.12,clearcoat:1}),ivory:physical('#f3ead7',{metalness:.05,roughness:.27}),black:physical('#12182a',{metalness:.22,roughness:.28}),red:physical('#bc1139',{metalness:.25,roughness:.18})};}
function mesh(g,m){const n=new THREE.Mesh(g,m);n.castShadow=true;n.receiveShadow=true;return n;}
function group(...children){const g=new THREE.Group();if(children.length)g.add(...children);return g;}
function roundedShape(w,h,r){const x=w/2,y=h/2,s=new THREE.Shape();r=Math.min(r,x*.8,y*.8);s.moveTo(-x+r,-y);s.lineTo(x-r,-y);s.quadraticCurveTo(x,-y,x,-y+r);s.lineTo(x,y-r);s.quadraticCurveTo(x,y,x-r,y);s.lineTo(-x+r,y);s.quadraticCurveTo(-x,y,-x,y-r);s.lineTo(-x,-y+r);s.quadraticCurveTo(-x,-y,-x+r,-y);return s;}
function polygon(points){const s=new THREE.Shape();for(let i=0;i<points.length;i++){const[x,y]=points[i];i?s.lineTo(x,y):s.moveTo(x,y);}s.closePath();return s;}
function uvNormalized(g){g.computeBoundingBox();const b=g.boundingBox,pos=g.attributes.position,uv=g.attributes.uv;if(!uv)return g;const w=b.max.x-b.min.x||1,h=b.max.y-b.min.y||1;for(let i=0;i<pos.count;i++)uv.setXY(i,(pos.getX(i)-b.min.x)/w,(pos.getY(i)-b.min.y)/h);return g;}
function extrude(s,d=.1,b=.025,smooth=true){const g=new THREE.ExtrudeGeometry(s,{depth:d,steps:1,bevelEnabled:b>0,bevelSize:b,bevelThickness:b,bevelSegments:3,curveSegments:16});g.translate(0,0,-d/2);uvNormalized(g);return smooth?smoothGeometryNormals(g):g;}
function box(w,h,d,m,r=.035){return mesh(extrude(roundedShape(w-r*2,h-r*2,r),Math.max(.01,d-r*2),r),m);}
function sphere(r,m,segments=24){return mesh(new THREE.SphereGeometry(r,segments,Math.max(12,segments*.7|0)),m);}
function disc(r,d,m,segments=48){const g=new THREE.CylinderGeometry(r,r,d,segments);g.rotateX(Math.PI/2);uvNormalized(g);return mesh(g,m);}
function cylinderY(r1,r2,h,m){return mesh(new THREE.CylinderGeometry(r1,r2,h,48),m);}
function ring(r,t,m){return mesh(new THREE.TorusGeometry(r,t,10,64),m);}
function tube(points,r,m,closed=false){const c=new THREE.CatmullRomCurve3(points.map(p=>point(...p)),closed);return mesh(new THREE.TubeGeometry(c,Math.max(18,points.length*5),r,8,closed),m);}
function placed(n,x=0,y=0,z=0,rz=0){n.position.set(x,y,z);n.rotation.z=rz;return n;}
function starShape(r=1,inner=.44,tips=5){return polygon(Array.from({length:tips*2},(_,i)=>{const a=Math.PI/2+i*Math.PI/tips,rr=i%2?inner*r:r;return[Math.cos(a)*rr,Math.sin(a)*rr];}));}
function star(r,m,tips=5){return mesh(extrude(starShape(r,tips===4?.17:.43,tips),r*.17,r*.025),m);}
function heart(r=1){const s=new THREE.Shape();s.moveTo(0,-r*.70);s.bezierCurveTo(-r*1.28,r*.08,-r*.60,r,0,r*.42);s.bezierCurveTo(r*.60,r,r*1.28,r*.08,0,-r*.70);return s;}
function spade(r=1){const s=new THREE.Shape();s.moveTo(0,r);s.bezierCurveTo(-.3*r,.65*r,-r,.17*r,-r,-.23*r);s.bezierCurveTo(-r,-.77*r,-.27*r,-.79*r,-.12*r,-.37*r);s.lineTo(-.29*r,-.89*r);s.lineTo(.29*r,-.89*r);s.lineTo(.12*r,-.37*r);s.bezierCurveTo(.27*r,-.79*r,r,-.77*r,r,-.23*r);s.bezierCurveTo(r,.17*r,.3*r,.65*r,0,r);return s;}
function letterA(size,m){const s=polygon([[-.37,0],[-.12,.9],[.12,.9],[.38,0],[.18,0],[.11,.24],[-.13,.24],[-.19,0]]);const hole=polygon([[-.08,.43],[.04,.43],[-.015,.67]]);s.holes.push(hole);const n=mesh(extrude(s,.025,.005),m);n.scale.setScalar(size);return n;}
function seven(m){return mesh(extrude(polygon([[-.35,.5],[.38,.5],[.38,.31],[.02,-.5],[-.22,-.5],[-.02,.12],[.1,.29],[-.35,.29]]),.06,.012),m);}
function coin(m){const g=group(disc(.8,.18,m.goldSide));g.add(placed(ring(.715,.034,m.pale),0,0,.105));g.add(placed(disc(.65,.025,m.gold),0,0,.105));g.add(placed(ring(.59,.013,m.pale),0,0,.126));g.add(placed(star(.36,m.pale),0,0,.152));for(let i=0;i<36;i++){const a=i/36*Math.PI*2;g.add(placed(box(.018,.076,.178,m.gold,.004),Math.sin(a)*.773,Math.cos(a)*.773,0,-a));}return g;}
function coinStack(m){const g=group();for(let i=0;i<4;i++){const c=coin(m);c.rotation.x=-Math.PI/2;c.position.set(-.30,-.69+i*.22,.02);g.add(c);}for(let i=0;i<3;i++){const c=coin(m);c.scale.setScalar(.76);c.rotation.x=-Math.PI/2;c.position.set(.62,-.74+i*.18,.25);g.add(c);}const upright=coin(m);upright.position.set(.15,.22,-.04);upright.rotation.set(.03,-.1,-.1);g.add(upright);return g;}
function chip(m,p){const g=group(disc(.83,.20,m.body));g.add(placed(ring(.77,.022,m.pale),0,0,.108));g.add(placed(ring(.58,.022,m.gold),0,0,.112));g.add(placed(disc(.5,.025,m.primary),0,0,.105));g.add(placed(star(.25,m.gold),0,0,.14));for(let i=0;i<8;i++){const a=i*Math.PI/4,n=box(.12,.19,.025,m.ivory,.009);placed(n,Math.sin(a)*.687,Math.cos(a)*.687,.107,-a);g.add(n);}return g;}
function chips(m,p){const g=group();for(let i=0;i<4;i++){const c=chip(m,p);c.rotation.set(-Math.PI/2,0,0);c.position.set(-.25,-.60+i*.25,.05);g.add(c);}const c=chip(m,p);c.position.set(.44,.19,.40);c.rotation.set(-.13,-.22,-.13);g.add(c);return g;}
function singleCard(m,red=false,dark=false){
 const front=dark?m.black:m.ivory,suit=dark?m.gold:(red?m.red:m.black),g=group(box(1.03,1.5,.085,front,.07));
 const border=roundedShape(.95,1.42,.055);border.holes.push(roundedShape(.926,1.396,.048));g.add(placed(mesh(extrude(border,.012,.002),dark?m.gold:m.pale),0,0,.092));
 g.add(placed(mesh(extrude((red?heart:spade)(.27),.025,.008),suit),0,0,.105));
 for(const side of[-1,1]){const corner=group(placed(letterA(.24,suit),-.03,0,0),placed(mesh(extrude((red?heart:spade)(.063),.02,.004),suit),0,-.105,0));corner.position.set(side*-.34,side*.40,.105);if(side<0)corner.rotation.z=Math.PI;g.add(corner);}return g;
}
function cards(m,p){const dark=p.id==='obsidian-gold',left=singleCard(m,false,dark),right=singleCard(m,true,dark);placed(left,-.35,.06,-.10,.24);placed(right,.35,-.02,.10,-.24);return group(left,right);}
function oneDie(m,p){const g=group(box(1.28,1.28,1.28,m.primary,.12));function dot(x,y,z,rx=0,ry=0){const n=disc(.096,.025,m.ivory,24);n.position.set(x,y,z);n.rotation.set(rx,ry,0);g.add(n);}
for(const[x,y]of[[-.3,-.3],[.3,.3],[0,0],[-.3,.3],[.3,-.3]])dot(x,y,.645);for(const[z,y]of[[-.28,-.28],[.28,.28],[0,0]])dot(.645,y,z,0,Math.PI/2);for(const[x,z]of[[-.27,-.27],[.27,.27]])dot(x,.645,z,-Math.PI/2,0);return g;}
function dice(m,p){const a=oneDie(m,p),b=oneDie(m,p);a.scale.setScalar(.84);a.position.set(-.43,-.18,.2);a.rotation.set(.05,-.12,.16);b.scale.setScalar(.76);b.position.set(.54,.40,-.10);b.rotation.set(.10,.12,-.2);return group(a,b);}
function diamond(m,p,doc,o){const n=8,positions=[],uvs=[],groups=[],faces=[];const rings=[{r:.51,y:.57,offset:0},{r:.92,y:.12,offset:Math.PI/n},{r:.92,y:-.02,offset:Math.PI/n},{r:0,y:-1.0,offset:0}];const vertex=(r,i)=>{const ring=rings[r],a=i*2*Math.PI/n+ring.offset;return [Math.cos(a)*ring.r,ring.y,Math.sin(a)*ring.r];};function tri(a,b,c,matId){const at=positions.length/3;positions.push(...a,...b,...c);for(const q of[a,b,c])uvs.push((q[0]+1)/2,(q[1]+1)/1.57);groups.push({start:at,count:3,materialIndex:matId});}
for(let i=0;i<n;i++){const next=(i+1)%n;tri([0,.57,0],vertex(0,next),vertex(0,i),1+i%3);tri(vertex(0,i),vertex(0,next),vertex(1,i),i%4);tri(vertex(0,next),vertex(1,next),vertex(1,i),(i+1)%4);tri(vertex(1,i),vertex(1,next),vertex(2,i),4);tri(vertex(1,next),vertex(2,next),vertex(2,i),4);tri(vertex(2,i),vertex(2,next),[0,-1,0],i%4);}
const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uvs,2));g.computeVertexNormals();for(const a of groups)g.addGroup(a.start,a.count,a.materialIndex);const mats=[0,.10,.27,-.40].map(t=>{const col=t<0?mix(p.gem,'#090826',-t):mix(p.gem,'#ecfaff',t),material=rampMaterial(col,doc,o.gloss,'lacquer');material.metalness=.49;material.roughness=.10;material.clearcoat=1;material.specularIntensity=1.35;material.side=THREE.DoubleSide;return material;});mats.push(physical(mix(p.gem,'#07051f',.46),{metalness:.55,roughness:.18,side:THREE.DoubleSide}));const obj=group(mesh(g,mats));for(let i=0;i<n;i++){const a=vertex(0,i),b=vertex(1,i);obj.add(tube([a,b],.0045,m.pale));}obj.rotation.y=.18;return obj;}
function crown(m,p){const g=group();const profile=[[.80,-.62],[.88,-.59],[.88,-.35],[.80,-.31],[.71,-.34],[.71,-.58],[.80,-.62]].map(a=>new THREE.Vector2(...a));g.add(mesh(new THREE.LatheGeometry(profile,64),m.gold));for(const y of[-.60,-.33]){const r=ring(.82,.04,m.pale);r.rotation.x=Math.PI/2;r.position.y=y;g.add(r);}for(let i=0;i<7;i++){const a=i*Math.PI*2/7,high=i%2?.70:.92,s=new THREE.Shape();s.moveTo(-.34,-.35);s.lineTo(.34,-.35);s.bezierCurveTo(.25,.05,.13,.09,.07,high-.14);s.quadraticCurveTo(0,high+.02,-.07,high-.14);s.bezierCurveTo(-.13,.09,-.25,.05,-.34,-.35);const tooth=mesh(extrude(s,.065,.018),[m.gold,m.goldSide]);tooth.position.set(Math.sin(a)*.77,0,Math.cos(a)*.77);tooth.rotation.y=a;g.add(tooth);const bead=sphere(.095,m.pale,20);bead.position.set(Math.sin(a)*.77,high-.08,Math.cos(a)*.77);g.add(bead);const gem=sphere(.12,m.gem,16);gem.scale.z=.48;gem.position.set(Math.sin(a)*.89,-.46,Math.cos(a)*.89);gem.rotation.y=a;g.add(gem);}return g;}
function ribbonLoop(side,m){
 const points=[[-.02,.11,.05],[side*.29,.58,-.04],[side*.58,.65,.11],[side*.63,.38,.22],[side*.35,.12,.19],[-.02,.11,.05]],curve=new THREE.CatmullRomCurve3(points.map(a=>point(...a))),count=48,pos=[],uv=[],idx=[];
 for(let i=0;i<=count;i++){const t=i/count,c=curve.getPoint(t),tan=curve.getTangent(t),normal=point(-tan.y,tan.x,0).normalize();for(const z of[.018,-.018])for(const sign of[-1,1]){pos.push(c.x+normal.x*.10*sign,c.y+normal.y*.10*sign,c.z+z);uv.push((c.x+.75)/1.5,c.y/.72);}}
 for(let i=0;i<count;i++){const k=i*4;idx.push(k,k+4,k+1,k+1,k+4,k+5,k+2,k+3,k+6,k+3,k+7,k+6,k,k+2,k+4,k+2,k+6,k+4,k+1,k+5,k+3,k+3,k+5,k+7);}
 const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));geo.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));geo.setIndex(idx);geo.computeVertexNormals();return mesh(geo,m.gold);
}
function gift(m,p){const g=group(box(1.5,1.25,1.25,m.body,.06));g.add(placed(box(1.64,.24,1.39,m.primary,.045),0,.65,0));g.add(placed(box(.28,1.38,1.29,m.gold,.015),0,.04,.015));g.add(placed(box(1.52,.27,1.30,m.gold,.015),0,.05,.025));g.add(placed(box(.30,.055,1.4,m.pale,.01),0,.81,0));g.add(placed(box(1.63,.055,.28,m.gold,.01),0,.81,0));const bow=group(ribbonLoop(-1,m),ribbonLoop(1,m),placed(box(.27,.25,.25,m.pale,.035),0,.13,.08));bow.position.set(0,.85,.12);g.add(bow);for(const side of[-1,1]){const strip=mesh(extrude(polygon([[0,.15],[side*.25,.1],[side*.43,-.52],[side*.22,-.45],[side*.09,-.61],[-.03,-.04]]),.025,.008),m.gold);strip.position.set(side*.05,.83,.73);g.add(strip);}return g;}
function trophy(m,p){const g=group();const profile=[[0,-.08],[.25,-.08],[.43,.13],[.63,.51],[.70,.94],[.67,1.00],[.59,1.00],[.55,.58],[.35,.17],[.2,.04],[0,.04]].map(a=>new THREE.Vector2(...a));g.add(mesh(new THREE.LatheGeometry(profile,64),m.gold));g.add(placed(cylinderY(.11,.21,.65,m.gold),0,-.39));g.add(placed(cylinderY(.41,.5,.13,m.gold),0,-.75));g.add(placed(box(1.0,.3,.85,m.black,.045),0,-.96));g.add(placed(box(.49,.13,.035,m.gold,.012),0,-.93,.443));for(const side of[-1,1]){const handle=tube([[side*.62,.83,0],[side*1.0,.89,0],[side*1.03,.48,0],[side*.76,.13,0],[side*.42,.07,0]],.055,m.pale);g.add(handle);}g.add(placed(star(.19,m.pale),0,.48,.62));return g;}
function medal(m,p){const g=group();for(const side of[-1,1]){const ribbon=mesh(extrude(polygon([[side*.06,.62],[side*.46,.77],[side*.62,-.92],[side*.35,-.78],[side*.14,-1.04]]),.06,.012),[m.primary,m.dark]);ribbon.position.z=-.15;g.add(ribbon);}const c=coin(m);c.scale.setScalar(.86);c.position.set(0,.18,.08);g.add(c);const loop=ring(.13,.035,m.gold);loop.position.set(0,.89,.08);g.add(loop);return g;}
function shield(m,p){const shape=polygon([[-.84,.87],[0,1.05],[.84,.87],[.78,-.25],[.47,-.7],[0,-1.01],[-.47,-.7],[-.78,-.25]]),g=group(mesh(extrude(shape,.20,.06),[m.gold,m.goldSide]));const front=mesh(extrude(shape,.05,.025),[m.primary,m.dark]);front.scale.set(.86,.86,1);front.position.z=.16;g.add(front);const s=star(.46,m.gold);s.position.z=.24;g.add(s);return g;}
function slotMachine(m,p){const g=group(box(1.74,2.03,.94,m.body,.10));g.add(placed(box(1.64,.28,1.0,m.gold,.06),0,-1.05,0));g.add(placed(box(1.60,.54,.12,m.gold,.065),0,.72,.51));g.add(placed(box(1.38,.36,.06,m.dark,.035),0,.73,.60));for(const x of[-.44,0,.44])g.add(placed(star(.13,m.pale),x,.73,.65));g.add(placed(box(1.58,.92,.14,m.gold,.055),0,.01,.52));g.add(placed(box(1.45,.77,.08,m.black,.038),0,.01,.63));for(const x of[-.47,0,.47]){g.add(placed(box(.39,.62,.10,m.ivory,.04),x,.01,.70));const sym=seven(m.red);sym.scale.setScalar(.39);sym.position.set(x,.01,.79);g.add(sym);}g.add(placed(box(1.22,.40,.15,m.primary,.035),0,-.63,.54));g.add(placed(box(.66,.08,.03,m.black,.01),-.10,-.61,.635));g.add(placed(sphere(.09,m.pale,20),.47,-.63,.64));const stem=cylinderY(.045,.055,.88,m.gold);stem.position.set(1.12,.07,.02);g.add(stem);const joint=cylinderY(.1,.1,.25,m.gold);joint.rotation.z=Math.PI/2;joint.position.set(.98,-.36,.02);g.add(joint);g.add(placed(sphere(.18,m.red),1.12,.55,.02));return g;}
function wheelWedge(r1,r2,a,b){const s=new THREE.Shape();s.moveTo(Math.cos(a)*r1,Math.sin(a)*r1);s.lineTo(Math.cos(a)*r2,Math.sin(a)*r2);s.absarc(0,0,r2,a,b,false);s.lineTo(Math.cos(b)*r1,Math.sin(b)*r1);s.absarc(0,0,r1,b,a,true);return s;}
function roulette(m,p){const g=group(disc(1.02,.22,m.goldSide));g.add(placed(ring(.97,.048,m.pale),0,0,.13));g.add(placed(disc(.90,.04,m.gold),0,0,.13));for(let i=0;i<24;i++){const a=i/24*Math.PI*2+.006,b=(i+1)/24*Math.PI*2-.006;const wedge=mesh(extrude(wheelWedge(.41,.83,a,b),.035,.006),i===0?m.body:i%2?m.red:m.black);wedge.position.z=.172;g.add(wedge);const line=box(.012,.39,.018,m.pale,.003),mid=(a+b)/2;line.position.set(Math.cos(mid)*.61,Math.sin(mid)*.61,.20);line.rotation.z=mid-Math.PI/2;g.add(line);}g.add(placed(ring(.85,.025,m.pale),0,0,.20));g.add(placed(ring(.39,.028,m.gold),0,0,.23));g.add(placed(disc(.31,.10,m.gold),0,0,.20));g.add(placed(sphere(.16,m.pale),0,0,.35));for(let i=0;i<4;i++){const a=i*Math.PI/2;const bar=box(.52,.035,.035,m.pale,.008);bar.position.set(Math.cos(a)*.17,Math.sin(a)*.17,.35);bar.rotation.z=a;g.add(bar);}g.add(placed(sphere(.045,m.ivory,16),.62,.28,.23));g.rotation.x=.12;return g;}
function chest(m,p){const g=group(box(1.75,.86,1.1,m.body,.08));g.add(placed(box(1.81,.11,1.16,m.gold,.018),0,-.43));g.add(placed(box(1.81,.09,1.16,m.gold,.018),0,.43));for(const x of[-.61,.61])g.add(placed(box(.13,.86,1.13,m.gold,.015),x,0));const dark=box(1.55,.10,.91,m.black,.03);dark.position.y=.40;g.add(dark);const lid=group(box(1.8,.54,1.15,m.body,.08));lid.add(placed(box(1.82,.075,1.17,m.gold,.015),0,-.25));for(const x of[-.61,.61])lid.add(placed(box(.13,.53,1.17,m.gold,.015),x,0));lid.position.set(0,.98,-.30);lid.rotation.x=-.85;g.add(lid);for(let i=0;i<7;i++){const c=coin(m);c.scale.setScalar(.29+(i%2)*.02);c.rotation.set(-.50,(i%3-.8)*.5,(i%3-.7)*.22);c.position.set((i%3-1)*.46,.48+Math.floor(i/3)*.15,(Math.floor(i/3)-.5)*.25);g.add(c);}const clasp=box(.29,.36,.10,m.gold,.035);clasp.position.set(0,.20,.61);g.add(clasp);g.add(placed(disc(.05,.025,m.black,20),0,.18,.68));return g;}
function wallet(m,p){const g=group();for(let i=0;i<2;i++){const card=box(1.20,.85,.06,i?m.primary:m.gold,.05);card.position.set((i-.5)*.28,.52,-.16-i*.12);card.rotation.z=(i-.5)*-.18;g.add(card);}g.add(placed(box(1.72,1.10,.58,m.body,.11),0,-.14,.03));g.add(placed(box(1.57,.96,.045,m.dark,.08),0,-.14,.345));g.add(placed(box(1.48,.88,.04,m.body,.065),0,-.14,.38));for(let i=0;i<12;i++){g.add(placed(box(.045,.012,.012,m.pale,.003),-.63+i*.115,.20,.409));g.add(placed(box(.045,.012,.012,m.pale,.003),-.63+i*.115,-.49,.409));}g.add(placed(box(.68,.34,.13,m.primary,.065),.62,-.13,.46));g.add(placed(disc(.095,.035,m.gold,32),.44,-.13,.54));const c=coin(m);c.scale.setScalar(.5);c.position.set(-.56,.63,.27);g.add(c);return g;}
function laurel(m){const g=group();for(const side of[-1,1]){const pts=Array.from({length:20},(_,i)=>{const a=-1.25+i/19*2.4;return[side*(.22+Math.cos(a)*.63),Math.sin(a)*.94,0];});g.add(tube(pts,.025,m.gold));for(let i=0;i<8;i++){const a=-1.12+i/7*2.13;for(const direction of[-1,1]){const leaf=sphere(1,m.gold,16);leaf.scale.set(.09,.23,.045);leaf.position.set(side*(.22+Math.cos(a)*.63)+direction*.08,Math.sin(a)*.94,.035);leaf.rotation.z=-side*a*.5+direction*.52;g.add(leaf);}}}return g;}
function football(m,p){
 const g=group(sphere(1,m.ivory,48)),phi=(1+Math.sqrt(5))/2,vertices=[[0,1,phi],[0,-1,phi],[0,1,-phi],[0,-1,-phi],[1,phi,0],[-1,phi,0],[1,-phi,0],[-1,-phi,0],[phi,0,1],[phi,0,-1],[-phi,0,1],[-phi,0,-1]];
 for(const v of vertices){const n=point(...v).normalize(),base=Math.abs(n.y)>.8?point(1,0,0):point(0,1,0),u=new THREE.Vector3().crossVectors(n,base).normalize(),w=new THREE.Vector3().crossVectors(n,u).normalize(),corners=[];
  for(let j=0;j<5;j++){const a=j*Math.PI*2/5;corners.push(n.clone().addScaledVector(u,Math.cos(a)*.30).addScaledVector(w,Math.sin(a)*.30).normalize());}
  const pos=[],norm=[],steps=6,add=(a,b,c)=>{for(const q of[a,b,c]){const unit=q.clone().normalize();pos.push(...unit.clone().multiplyScalar(1.012).toArray());norm.push(...unit.toArray());}};
  for(let j=0;j<5;j++){const a=n,b=corners[j],c=corners[(j+1)%5],q=(i,k)=>a.clone().multiplyScalar(1-(i+k)/steps).addScaledVector(b,i/steps).addScaledVector(c,k/steps);
   for(let i=0;i<steps;i++)for(let k=0;k<steps-i;k++){add(q(i,k),q(i+1,k),q(i,k+1));if(i+k+2<=steps)add(q(i+1,k),q(i+1,k+1),q(i,k+1));}}
  const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));geo.setAttribute('normal',new THREE.Float32BufferAttribute(norm,3));const patchMat=m.black.clone();patchMat.side=THREE.DoubleSide;g.add(mesh(geo,patchMat));
  const outline=[];for(let j=0;j<5;j++)for(let k=0;k<6;k++)outline.push(corners[j].clone().lerp(corners[(j+1)%5],k/6).normalize().multiplyScalar(1.015).toArray());g.add(tube(outline,.007,m.dark,true));
 }
 const band=ring(1.09,.022,m.gold);band.rotation.set(.35,.12,-.26);g.add(band);return g;
}
function basketball(m,p){const copper=rampMaterial('#db6b20',p.doc,p.gloss,'lacquer'),g=group(sphere(1,copper,40));for(const rot of[[0,0,0],[Math.PI/2,0,0],[0,Math.PI/2,0]]){const seam=ring(1.003,.018,m.black);seam.rotation.set(...rot);g.add(seam);}for(const side of[-1,1]){const pts=Array.from({length:40},(_,i)=>{const a=i/39*Math.PI*2,z=.5*Math.cos(a);return point(side*Math.sqrt(Math.max(0,1-z*z))*.77,Math.sin(a)*.68,z).normalize().multiplyScalar(1.006).toArray();});g.add(tube(pts,.017,m.black));}return g;}
function lightning(m){return group(mesh(extrude(polygon([[.15,1],[-.68,-.09],[-.12,-.09],[-.25,-1],[.72,.25],[.14,.25]]),.16,.026),[m.gold,m.goldSide]));}
function makeModel(kind,m,p,doc,o){switch(kind){case'coin':return coin(m);case'coin-stack':return coinStack(m);case'chip':return chip(m,p);case'chips':return chips(m,p);case'cards':return cards(m,p);case'dice':return dice(m,p);case'crown':return crown(m,p);case'diamond':case'gem':return diamond(m,p,doc,o);case'gift':return gift(m,p);case'trophy':return trophy(m,p);case'medal':return medal(m,p);case'shield':return shield(m,p);case'slot-machine':return slotMachine(m,p);case'roulette':return roulette(m,p);case'chest':return chest(m,p);case'wallet':return wallet(m,p);case'football':return football(m,p);case'basketball':return basketball(m,{...p,doc,gloss:o.gloss});case'laurel':return laurel(m);case'lightning':return lightning(m);case'sparkle':return group(star(1,m.pale,4));case'star':return group(star(1,m.gold));case'ring':return group(ring(1,.045,m.gold));default:throw new Error('不支持的图标模型。');}}
function environment(doc){if(environments.has(doc))return environments.get(doc);const w=512,h=256,data=new Uint8Array(w*h*4);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const u=x/w,v=y/h,soft=(cx,cy,wx,wy)=>Math.exp(-(((u-cx)/wx)**2+((v-cy)/wy)**2)*2),light=soft(.22,.28,.14,.065)*2.8+soft(.73,.44,.035,.24)*1.8+soft(.56,.78,.22,.033)*.65,at=(y*w+x)*4;data[at]=Math.min(255,14+light*126);data[at+1]=Math.min(255,17+light*121);data[at+2]=Math.min(255,27+light*111);data[at+3]=255;}const t=new THREE.DataTexture(data,w,h,THREE.RGBAFormat);t.mapping=THREE.EquirectangularReflectionMapping;t.colorSpace=THREE.SRGBColorSpace;t.needsUpdate=true;environments.set(doc,t);return t;}
function engine(doc){if(engines.has(doc))return engines.get(doc);const canvas=doc.createElement('canvas');let renderer=null;try{const attrs={alpha:true,antialias:true,preserveDrawingBuffer:true,powerPreference:'high-performance'},context=canvas.getContext('webgl2',attrs);if(context){renderer=new THREE.WebGLRenderer({canvas,context,...attrs});renderer.setPixelRatio(1);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=.91;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;}}catch{renderer=null;}const result={canvas,renderer};engines.set(doc,result);return result;}
function lighting(scene,o,p,doc){scene.environment=environment(doc);scene.environmentIntensity=.85;scene.add(new THREE.HemisphereLight('#ecf1ff','#16091f',.55));const a=radians(o.lightDirection),w=o.width,h=o.height,key=new THREE.DirectionalLight('#fff5e3',2.8);key.position.set(w/2+Math.sin(a)*700,h/2+Math.cos(a)*700,800);key.target.position.set(w/2,h/2,0);scene.add(key,key.target);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.bias=-.0002;key.shadow.normalBias=.4;const bound=Math.max(w,h);Object.assign(key.shadow.camera,{left:-bound,right:bound,top:bound,bottom:-bound,near:10,far:4000});const fill=new THREE.DirectionalLight('#b0d9ff',.45);fill.position.set(w/2-Math.sin(a)*600,h*.2,500);fill.target.position.set(w/2,h/2,0);scene.add(fill,fill.target);const rim=new THREE.DirectionalLight(p.gem,.75+o.glow/100);rim.position.set(w*.9,h*.8,-400);rim.target.position.set(w/2,h/2,0);scene.add(rim,rim.target);}
function disposeScene(scene){const gs=new Set(),ms=new Set();scene.traverse(n=>{if(n.geometry)gs.add(n.geometry);if(n.material)for(const m of Array.isArray(n.material)?n.material:[n.material])ms.add(m);n.shadow?.map?.dispose();});for(const g of gs)g.dispose();for(const m of ms){m.map?.dispose();m.dispose();}}
function bounds2d(object,camera,w,h){const b=new THREE.Box3().setFromObject(object),xs=[],ys=[];for(const x of[b.min.x,b.max.x])for(const y of[b.min.y,b.max.y])for(const z of[b.min.z,b.max.z]){const p=point(x,y,z).project(camera);xs.push((p.x+1)*w/2);ys.push((1-p.y)*h/2);}return{x:Math.min(...xs),y:Math.min(...ys),width:Math.max(...xs)-Math.min(...xs),height:Math.max(...ys)-Math.min(...ys)};}
export function renderIconScene(canvas,o,p){
  const doc=canvas.ownerDocument||globalThis.document;if(!doc?.createElement)throw new Error('图标渲染需要可用的画布环境。');
  const w=o.width,h=o.height,scene=new THREE.Scene(),camera=new THREE.OrthographicCamera(0,w,h,0,.1,10000),objects=[];camera.position.set(0,0,3000);camera.lookAt(0,0,0);camera.updateProjectionMatrix();camera.updateMatrixWorld(true);lighting(scene,o,p,doc);
  const mats=materials(p,doc,o);let depth=0;
  for(const layer of o.layers){if(layer.hidden)continue;const geometry=makeModel(layer.kind,mats,p,doc,o),angleRoot=group(geometry);angleRoot.rotation.set(radians(o.pitch),radians(o.yaw),-radians(layer.rotation));angleRoot.updateMatrixWorld(true);let bounds=new THREE.Box3().setFromObject(angleRoot),center=bounds.getCenter(new THREE.Vector3()),size=bounds.getSize(new THREE.Vector3());const root=group(angleRoot);angleRoot.position.sub(center);const scale=Math.min(w*.65/Math.max(.01,size.x),h*.65/Math.max(.01,size.y))*layer.scale;root.scale.setScalar(scale);root.position.set(w*(.5+layer.x),h*(.5-layer.y),0);root.updateMatrixWorld(true);bounds=new THREE.Box3().setFromObject(root);root.position.z=depth-bounds.min.z;depth+=bounds.max.z-bounds.min.z+20;scene.add(root);objects.push({id:layer.id,object:root});}
  camera.position.z=Math.max(3000,depth+1500);camera.far=camera.position.z+3000;camera.updateProjectionMatrix();camera.updateMatrixWorld(true);scene.updateMatrixWorld(true);
  const hitRegions=objects.map(({id,object})=>({id,bounds:bounds2d(object,camera,w,h)}));const raw=doc.createElement('canvas');raw.width=w;raw.height=h;let mode;
  try{const{renderer}=engine(doc);if(renderer){renderer.setSize(w,h,false);renderer.setClearColor('#000000',0);renderer.render(scene,camera);raw.getContext('2d').drawImage(renderer.domElement,0,0,w,h);mode={engine:'three-webgl-casino-icon-3d',geometry:true,graphicsMode:'hardware'};}else mode={...renderSoftwareScene(raw,scene,camera,{...o,transparent:true}),engine:'cpu-triangle-casino-icon-3d'};const effects=compositeArtwork(canvas,raw,o,{glow:p.gem,accent:p.accent});return {...mode,...effects,hitRegions,modelCount:objects.length,rendererVersion:6};}finally{disposeScene(scene);for(const material of Object.values(mats)){material.map?.dispose();material.dispose();}}
}
